/*
 Problem: 1140. Stone Game II
 Language: cpp
 Runtime: 47 ms (12.39%)
 Memory: 14 MB (21.05%)
 Tags: Array, Math, Dynamic Programming, Minimax, Prefix Sum, Game Theory, Zero-Sum Game
*/
class Solution {
public:
    int stoneGameII(vector<int>& piles) {
        int n = piles.size();
        vector<int> suf(n + 1);

        for (int i = n - 1; i >= 0; --i)
            suf[i] = suf[i + 1] + piles[i];

        vector<vector<int>> dp(n + 5, vector<int>(n + 5));

        for (int i = n - 1; i >= 0; --i) {
            for (int m = 1; m <= n; ++m) {
                for (int x = 1; x <= 2 * m && i + x <= n; ++x)
                    dp[i][m] = max(dp[i][m],
                        suf[i] - dp[i + x][max(m, x)]);
            }
        }

        return dp[0][1];
    }
};
